import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [phones, setPhones] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/phones')
      .then(res => setPhones(res.data))
      .catch(err => console.error('Lỗi khi lấy dữ liệu:', err));
  }, []);

  return (
    <div className="container my-4">
      <h1 className="mb-4 text-center">Shop Điện Thoại</h1>
      <div className="row">
        {phones.length === 0 ? (
          <p className="text-center w-100">Đang tải danh sách điện thoại...</p>
        ) : (
          phones.map(phone => (
            <div key={phone._id} className="col-md-4 mb-4">
              <div className="card h-100 shadow-sm">
                <img src={phone.image} className="card-img-top" alt={phone.name} style={{ height: '250px', objectFit: 'cover' }} />
                <div className="card-body d-flex flex-column">
                  <h5 className="card-title">{phone.name}</h5>
                  <p className="card-text">{phone.description}</p>
                  <div className="mt-auto">
                    <p className="fw-bold">Giá: {phone.price.toLocaleString()} VND</p>
                    <a href="#" className="btn btn-primary w-100">Xem chi tiết</a>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default App;
